"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import Image from "next/image";

interface MusicCard {
  id: string;
  createdAt: string;
  title: string;
  artist: string;
  coverUrl: string;
  originalUrl: string;
  platform: string;
  template: string;
  displayTitle?: string;
}

interface HistoryResponse {
  success: boolean;
  data: {
    musicCards: MusicCard[];
    pagination: {
      page: number;
      limit: number;
      total: number;
      totalPages: number;
    };
  };
}

export default function HistoryPage() {
  const [musicCards, setMusicCards] = useState<MusicCard[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 20,
    total: 0,
    totalPages: 0,
  });

  const fetchHistory = async (pageNum: number = 1) => {
    try {
      setLoading(true);
      const response = await fetch(`/api/music-cards?page=${pageNum}&limit=20`);
      const data: HistoryResponse = await response.json();

      if (data.success) {
        setMusicCards(data.data.musicCards);
        setPagination(data.data.pagination);
      } else {
        setError("获取历史记录失败");
      }
    } catch (err) {
      setError("网络请求失败");
      console.error("获取历史记录失败:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchHistory(page);
  }, [page]);

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString("zh-CN", {
      year: "numeric",
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  const getTemplateUrl = (card: MusicCard) => {
    const baseUrl = card.template === "phone" ? "/phone" : "/poster";
    return `${baseUrl}?url=${encodeURIComponent(card.originalUrl)}`;
  };

  if (loading && musicCards.length === 0) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto"></div>
          <p className="mt-4 text-gray-600">加载历史记录中...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* 导航栏 */}
      <nav className="bg-white shadow-sm border-b">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center space-x-4">
              <Link
                href="/"
                className="flex items-center text-gray-600 hover:text-gray-900 transition-colors"
              >
                <span className="material-symbols-outlined mr-2">home</span>
                返回首页
              </Link>
            </div>
            <h1 className="text-lg font-semibold text-gray-900">生成历史</h1>
            <div className="w-20"></div> {/* 占位符保持居中 */}
          </div>
        </div>
      </nav>

      {/* 主内容 */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {error ? (
          <div className="text-center py-12">
            <p className="text-red-600 mb-4">{error}</p>
            <button
              onClick={() => fetchHistory(page)}
              className="px-4 py-2 bg-blue-500 text-white rounded-md hover:bg-blue-600 transition-colors"
            >
              重试
            </button>
          </div>
        ) : musicCards.length === 0 ? (
          <div className="text-center py-12">
            <div className="text-gray-400 mb-4">
              <span className="material-symbols-outlined text-6xl">music_note</span>
            </div>
            <h3 className="text-lg font-medium text-gray-900 mb-2">
              还没有生成记录
            </h3>
            <p className="text-gray-500 mb-6">
              创建你的第一个音乐海报吧！
            </p>
            <Link
              href="/"
              className="inline-flex items-center px-4 py-2 bg-blue-500 text-white rounded-md hover:bg-blue-600 transition-colors"
            >
              开始生成
            </Link>
          </div>
        ) : (
          <>
            {/* 统计信息 */}
            <div className="mb-6">
              <h2 className="text-2xl font-bold text-gray-900 mb-2">
                我的生成记录
              </h2>
              <p className="text-gray-600">
                共 {pagination.total} 条记录
              </p>
            </div>

            {/* 卡片网格 */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {musicCards.map((card) => (
                <Link
                  key={card.id}
                  href={getTemplateUrl(card)}
                  className="group block"
                >
                  <div className="bg-white rounded-lg shadow-sm border hover:shadow-md transition-all duration-200 overflow-hidden">
                    {/* 专辑封面 */}
                    <div className="aspect-square relative">
                      <Image
                        src={card.coverUrl}
                        alt={card.title}
                        fill
                        className="object-cover group-hover:scale-105 transition-transform duration-200"
                        sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 25vw"
                      />
                      {/* 模板标识 */}
                      <div className="absolute top-2 right-2">
                        <span className={`px-2 py-1 text-xs font-medium rounded-full ${
                          card.template === "phone"
                            ? "bg-blue-100 text-blue-800"
                            : "bg-green-100 text-green-800"
                        }`}>
                          {card.template === "phone" ? "Phone" : "Poster"}
                        </span>
                      </div>
                    </div>

                    {/* 卡片信息 */}
                    <div className="p-4">
                      <h3 className="font-medium text-gray-900 truncate mb-1">
                        {card.displayTitle || card.title}
                      </h3>
                      <p className="text-sm text-gray-600 truncate mb-2">
                        {card.artist}
                      </p>
                      <div className="flex items-center justify-between text-xs text-gray-500">
                        <span className="capitalize">{card.platform}</span>
                        <span>{formatDate(card.createdAt)}</span>
                      </div>
                    </div>
                  </div>
                </Link>
              ))}
            </div>

            {/* 分页 */}
            {pagination.totalPages > 1 && (
              <div className="mt-8 flex justify-center">
                <nav className="flex items-center space-x-2">
                  <button
                    onClick={() => setPage(Math.max(1, page - 1))}
                    disabled={page === 1}
                    className="px-3 py-2 rounded-md border border-gray-300 bg-white text-sm font-medium text-gray-500 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    上一页
                  </button>
                  
                  {/* 页码 */}
                  {Array.from({ length: pagination.totalPages }, (_, i) => i + 1).map((pageNum) => (
                    <button
                      key={pageNum}
                      onClick={() => setPage(pageNum)}
                      className={`px-3 py-2 rounded-md text-sm font-medium ${
                        pageNum === page
                          ? "bg-blue-500 text-white"
                          : "border border-gray-300 bg-white text-gray-500 hover:bg-gray-50"
                      }`}
                    >
                      {pageNum}
                    </button>
                  ))}

                  <button
                    onClick={() => setPage(Math.min(pagination.totalPages, page + 1))}
                    disabled={page === pagination.totalPages}
                    className="px-3 py-2 rounded-md border border-gray-300 bg-white text-sm font-medium text-gray-500 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    下一页
                  </button>
                </nav>
              </div>
            )}
          </>
        )}
      </main>
    </div>
  );
} 